import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, lessThan, greaterThan, oneMinus, mul, add, sub } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, Vector3 } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // --------------------------------------------------------------------
  // 1. Backdrop / Gradient Plane (fills the whole scene area, used for fade)
  // --------------------------------------------------------------------
  const backdropWidth = 7.0;
  const backdropHeight = 6.0; // large enough to cover view, z = -2.5 per spec
  const backdropGeom = new PlaneGeometry(backdropWidth, backdropHeight);
  const backdropMaterial = new MeshStandardNodeMaterial({
    color: new Color('#0b0b10'),
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });

  // Gradient mask based on uv.x (horizontal fade)
  const uvNode = uv();
  const maskLeft = smoothstep(0.0, 0.09, uvNode.x);
  const maskRight = oneMinus(smoothstep(0.91, 1.0, uvNode.x));
  const mask = mul(maskLeft, maskRight);
  backdropMaterial.opacityNode = mask;

  const backdrop = new Mesh(backdropGeom, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // --------------------------------------------------------------------
  // 2. Ribbon Plane
  // --------------------------------------------------------------------
  const ribbonWidth = 7.0;
  const ribbonHeight = 0.35;
  const ribbonGeom = new PlaneGeometry(ribbonWidth, ribbonHeight);
  const ribbonMaterial = new MeshStandardNodeMaterial({
    color: new Color('#111117'),
    roughness: 0.6,
    metalness: 0.2,
    side: ctx.THREE.DoubleSide,
  });

  // Apply the same edge fade to the ribbon (reuse mask)
  ribbonMaterial.opacityNode = mask;

  const ribbon = new Mesh(ribbonGeom, ribbonMaterial);
  ribbon.position.set(0, 0, 0);
  root.add(ribbon);

  // --------------------------------------------------------------------
  // 3. Top / Bottom Hairlines
  // --------------------------------------------------------------------
  const hairHeight = 0.006;
  const hairGeom = new PlaneGeometry(ribbonWidth, hairHeight);
  const hairMat = new MeshStandardNodeMaterial({
    color: new Color('#23232b'),
    roughness: 0.6,
    metalness: 0.0,
    side: ctx.THREE.DoubleSide,
  });

  const topHair = new Mesh(hairGeom, hairMat);
  topHair.position.set(0, ribbonHeight / 2 - hairHeight / 2, 0.001);
  const bottomHair = new Mesh(hairGeom, hairMat);
  bottomHair.position.set(0, -ribbonHeight / 2 + hairHeight / 2, 0.001);
  root.add(topHair, bottomHair);

  // --------------------------------------------------------------------
  // 4. Ticker Content Group (scrolling)
  // --------------------------------------------------------------------
  const scrollGroup = new Group();
  scrollGroup.position.z = 0.02; // lift just above ribbon plane
  root.add(scrollGroup);

  // Font style from spec
  const textOpts = {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0.06,
  };

  // Ticker strings
  const tickerItems = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18',
  ];

  // Approximate spacing constants (scene units)
  const gapBetweenTicks = 0.5; // gap on each side of tick
  const tickWidth = 0.02;
  const tickHeight = 0.14;
  const tickDepth = 0.001;

  const tickGeom = new BoxGeometry(tickWidth, tickHeight, tickDepth);
  const tickMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.5,
    metalness: 0,
    roughness: 0,
    side: ctx.THREE.DoubleSide,
  });

  // Helper to create a tick mesh
  const createTick = () => new Mesh(tickGeom, tickMat);

  // Layout algorithm (very rough, based on character count)
  let cursorX = -ribbonWidth / 2; // start at left edge

  const createEntry = (text) => {
    // Tick
    const tick = createTick();
    tick.position.set(cursorX + gapBetweenTicks + tickWidth / 2, 0, 0);
    scrollGroup.add(tick);
    cursorX += gapBetweenTicks + tickWidth + gapBetweenTicks; // left gap, tick, right gap

    // Text
    const txtObj = ctx.fontAtlas.createText(text, textOpts);
    // rough width estimation: characters * (fontSize * 0.06)
    const estWidth = text.length * (13 * 0.06);
    txtObj.position.set(cursorX + estWidth / 2, 0, 0);
    scrollGroup.add(txtObj);
    cursorX += estWidth;

    // Add a small extra gap after each entry to ensure spacing
    const extraGap = 0.3;
    cursorX += extraGap;
  };

  // Build first sequence
  for (const item of tickerItems) {
    createEntry(item);
  }

  // Record total length for duplication
  const totalLength = cursorX + ribbonWidth / 2; // distance from start to right edge

  // Duplicate sequence for seamless loop
  const duplicateGroup = scrollGroup.clone();
  duplicateGroup.position.x = totalLength;
  root.add(duplicateGroup);

  // --------------------------------------------------------------------
  // 5. Apply cinematic primitive (fly-through) to the scrolling container
  // --------------------------------------------------------------------
  const primitives = [];
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const p = ctx.primitives[prim.name];
      if (p) {
        const result = p(scrollGroup, prim.params);
        primitives.push(result);
      }
    }
  }

  // --------------------------------------------------------------------
  // 6. Cleanup
  // --------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMaterial.dispose();
    ribbonGeom.dispose();
    ribbonMaterial.dispose();
    hairGeom.dispose();
    hairMat.dispose();
    tickGeom.dispose();
    tickMat.dispose();

    // Dispose any text objects (fontAtlas may manage its own resources)
    scrollGroup.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
    });
    duplicateGroup.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
    });

    // Kill GSAP timelines if any (none created directly)
    gsap.globalTimeline.clear();

    // Cleanup primitives
    for (const p of primitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }

    // Remove from parent if attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
